urlset:
{# homepage - always publicly accessible, no reliable modification date so  is omitted #}

    {{ ''|url }}
    1.0
    daily


{# products - paginated so large catalogs are not truncated at the first page #}
{% set products = guest.product_get_list({"per_page": 500}) %}
{% for i, product in products.list %}

    {{ "order/#{product.slug}"|url }}
    {% set lastmod = product.updated_at ?? product.created_at ?? null %}
    {% if lastmod %}{{ lastmod|date('Y-m-d') }}{% endif %}
    0.9
    weekly

{% endfor %}
{% if products.pages > 1 %}
{% for page_number in 2..products.pages %}
{% set products_page = guest.product_get_list({"per_page": 500, "page": page_number}) %}
{% for i, product in products_page.list %}

    {{ "order/#{product.slug}"|url }}
    {% set lastmod = product.updated_at ?? product.created_at ?? null %}
    {% if lastmod %}{{ lastmod|date('Y-m-d') }}{% endif %}
    0.9
    weekly

{% endfor %}
{% endfor %}
{% endif %}

{# news items #}
{% if guest.extension_is_on({"mod":'news'}) %}
{% set news = guest.news_get_list({"per_page": 500}) %}
{% if news.total > 0 %}

    {{ 'news'|url }}
    0.8
    weekly

{% endif %}
{% for i, article in news.list %}

    {{ "news/#{article.slug}"|url }}
    {% set lastmod = article.updated_at ?? article.created_at ?? null %}
    {% if lastmod %}{{ lastmod|date('Y-m-d') }}{% endif %}
    0.9
    weekly

{% endfor %}
{% if news.pages > 1 %}
{% for page_number in 2..news.pages %}
{% set news_page = guest.news_get_list({"per_page": 500, "page": page_number}) %}
{% for i, article in news_page.list %}

    {{ "news/#{article.slug}"|url }}
    {% set lastmod = article.updated_at ?? article.created_at ?? null %}
    {% if lastmod %}{{ lastmod|date('Y-m-d') }}{% endif %}
    0.9
    weekly

{% endfor %}
{% endfor %}
{% endif %}
{% endif %}

{# knowledge base items #}
{% if guest.support_kb_enabled() %}
{% set kb = guest.support_kb_article_get_list({"per_page": 500}) %}
{% if kb.total > 0 %}

    {{ 'support/kb'|url }}
    0.8
    weekly

{% endif %}
{% for i, article in kb.list %}

    {{ "support/kb/#{article.category.slug}/#{article.slug}"|url }}
    {% set lastmod = article.updated_at ?? article.created_at ?? null %}
    {% if lastmod %}{{ lastmod|date('Y-m-d') }}{% endif %}
    0.9
    weekly

{% endfor %}
{% if kb.pages > 1 %}
{% for page_number in 2..kb.pages %}
{% set kb_page = guest.support_kb_article_get_list({"per_page": 500, "page": page_number}) %}
{% for i, article in kb_page.list %}

    {{ "support/kb/#{article.category.slug}/#{article.slug}"|url }}
    {% set lastmod = article.updated_at ?? article.created_at ?? null %}
    {% if lastmod %}{{ lastmod|date('Y-m-d') }}{% endif %}
    0.9
    weekly

{% endfor %}
{% endfor %}
{% endif %}
{% endif %}

{# custom pages - public alias is /page/:slug (rewritten to /custompages/:slug) #}
{% if guest.extension_is_on({"mod":'custompages'}) %}
{% set pages = guest.custompages_get_list({"per_page": 500}) %}
{% for i, page in pages.list %}

    {{ "page/#{page.slug}"|url }}
    {% set lastmod = page.updated_at ?? page.created_at ?? null %}
    {% if lastmod %}{{ lastmod|date('Y-m-d') }}{% endif %}
    0.8
    weekly

{% endfor %}
{% if pages.pages > 1 %}
{% for page_number in 2..pages.pages %}
{% set pages_page = guest.custompages_get_list({"per_page": 500, "page": page_number}) %}
{% for i, page in pages_page.list %}

    {{ "page/#{page.slug}"|url }}
    {% set lastmod = page.updated_at ?? page.created_at ?? null %}
    {% if lastmod %}{{ lastmod|date('Y-m-d') }}{% endif %}
    0.8
    weekly

{% endfor %}
{% endfor %}
{% endif %}
{% endif %}
